shell_commands:
node -e "
import('@re-cinq/eslint-plugin-re-lint/dist/vendor/spec/spec-status-coverage.js').then(({statementCoverage, unlinkedTestableStatements}) => {
  const fs = await import('node:fs');
  const content = fs.readFileSync('specs/hal-engine-config-hooks/spec.md', 'utf8');
  const result = statementCoverage(content);
  console.log('testable:', result.testable, 'linked:', result.linked);
  console.log('unlinked:', result.unlinked.map(s => s.text.slice(0, 80)));
}).catch(e => console.error(e));
" 2>&1 | head -30

node --input-type=module <<'EOF' 2>&1
import {statementCoverage} from './node_modules/@re-cinq/eslint-plugin-re-lint/dist/vendor/spec/spec-status-coverage.js';
import {readFileSync} from 'node:fs';
const content = readFileSync('specs/hal-engine-config-hooks/spec.md', 'utf8');
const result = statementCoverage(content);
console.log('testable:', result.testable, 'linked:', result.linked);
console.log('unlinked:', JSON.stringify(result.unlinked.map(s => s.text.slice(0, 100))));
EOF
